'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { BlocksIcon, SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import {
  CATEGORIES,
  INITIALLY_CONNECTED,
  INTEGRATIONS,
  PAGE,
  VIEWS,
  type Integration,
  type ViewId,
} from './data';
import { IntegrationCard, type ConnectState } from './integration-card';

const CONNECTING_MS = 900;

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const CARD_TRANSITION: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const CARD_EXIT: Transition = { duration: 0.12, ease: EASE_OUT_STRONG };

const CARD_LAYOUT: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

type ConnectStates = Record<string, ConnectState>;

function initialStatesOf(): ConnectStates {
  const states: ConnectStates = {};
  for (const integration of INTEGRATIONS) {
    const isConnected = INITIALLY_CONNECTED.includes(integration.id);
    if (isConnected) {
      states[integration.id] = 'connected';
    } else {
      states[integration.id] = 'idle';
    }
  }
  return states;
}

function isViewId(value: unknown): value is ViewId {
  return VIEWS.some((view) => view.id === value);
}

function matchesQuery(integration: Integration, query: string) {
  const needle = query.trim().toLowerCase();
  if (!needle) {
    return true;
  }
  const category = CATEGORIES[integration.category].label;
  const haystack = `${integration.name} ${integration.description} ${category}`;
  const lowered = haystack.toLowerCase();
  return lowered.includes(needle);
}

function matchesView(
  integration: Integration,
  view: ViewId,
  states: ConnectStates
) {
  if (view === 'all') {
    return true;
  }
  if (view === 'connected') {
    return states[integration.id] === 'connected';
  }
  return integration.category === view;
}

function connectedCountOf(states: ConnectStates) {
  const values = Object.values(states);
  const connected = values.filter((state) => state === 'connected');
  return connected.length;
}

function connectedNounOf(count: number) {
  if (count === 1) {
    return 'tool connected';
  }
  return 'tools connected';
}

function outcomeOf(integration: Integration, attempts: number): ConnectState {
  const isFirstAttempt = attempts === 0;
  const needsApproval = Boolean(integration.needsApproval);
  const isBlocked = needsApproval && isFirstAttempt;
  if (isBlocked) {
    return 'failed';
  }
  return 'connected';
}

function searchHintOf(view: ViewId) {
  if (view === 'all') {
    return 'Try the name of a tool or a word from what it does';
  }
  if (view === 'connected') {
    return 'Only connected tools are searched here, clear the search or open All';
  }
  const label = CATEGORIES[view].label;
  return `Only ${label} tools are searched here, clear the search or open All`;
}

type EmptyViewProps = {
  view: ViewId;
  query: string;
  onClearSearch: () => void;
  onBrowseAll: () => void;
};

function EmptyView({
  view,
  query,
  onClearSearch,
  onBrowseAll,
}: EmptyViewProps) {
  const trimmed = query.trim();
  const hasQuery = trimmed.length > 0;
  const isConnectedView = view === 'connected';

  if (!hasQuery && isConnectedView) {
    return (
      <div className='flex flex-col items-center px-6 py-12 text-center'>
        <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
          <BlocksIcon />
        </span>
        <p className='mt-4 text-sm font-medium'>Nothing connected yet</p>
        <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
          Connect a tool from the full list and it shows up here
        </p>
        <Button variant='outline' onClick={onBrowseAll} className='mt-4'>
          Browse all
        </Button>
      </div>
    );
  }

  return (
    <div className='flex flex-col items-center px-6 py-12 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        <SearchIcon />
      </span>
      <p className='mt-4 text-sm font-medium'>
        No integration matches “{trimmed}”
      </p>
      <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
        {searchHintOf(view)}
      </p>
      <Button variant='outline' onClick={onClearSearch} className='mt-4'>
        <XIcon />
        Clear search
      </Button>
    </div>
  );
}

export default function Integrations01() {
  const [states, setStates] = useState<ConnectStates>(initialStatesOf);
  const [attempts, setAttempts] = useState<Record<string, number>>({});
  const [view, setView] = useState<ViewId>('all');
  const [query, setQuery] = useState('');
  const timersRef = useRef(new Map<string, number>());
  const shouldReduceMotion = useReducedMotion();
  const allowsLayout = !shouldReduceMotion;
  const connectedCount = connectedCountOf(states);
  const visible = INTEGRATIONS.filter(
    (integration) =>
      matchesView(integration, view, states) && matchesQuery(integration, query)
  );
  const isEmpty = visible.length === 0;
  const hasQuery = query.length > 0;

  useEffect(() => {
    const timers = timersRef.current;
    return () => {
      for (const timer of timers.values()) {
        window.clearTimeout(timer);
      }
    };
  }, []);

  function setStateOf(id: string, state: ConnectState) {
    setStates((current) => ({ ...current, [id]: state }));
  }

  function finishConnecting(integration: Integration) {
    const attemptCount = attempts[integration.id] ?? 0;
    const outcome = outcomeOf(integration, attemptCount);
    setStateOf(integration.id, outcome);
    setAttempts((current) => ({
      ...current,
      [integration.id]: attemptCount + 1,
    }));
    timersRef.current.delete(integration.id);
  }

  function connect(integration: Integration) {
    setStateOf(integration.id, 'connecting');
    const timer = window.setTimeout(
      () => finishConnecting(integration),
      CONNECTING_MS
    );
    timersRef.current.set(integration.id, timer);
  }

  function disconnect(integration: Integration) {
    setStateOf(integration.id, 'idle');
  }

  function pickView(value: unknown) {
    if (isViewId(value)) {
      setView(value);
    }
  }

  function handleSearchKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      setQuery('');
    }
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <div className='mx-auto flex w-full max-w-5xl flex-col gap-5 px-4 py-6 md:px-6 md:py-10'>
        <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-2'>
          <div className='flex max-w-xl flex-col gap-1'>
            <h1 className='text-lg font-semibold text-balance'>{PAGE.title}</h1>
            <p className='text-muted-foreground text-[13px] text-pretty'>
              {PAGE.description}
            </p>
          </div>
          <p className='text-muted-foreground text-[13px]'>
            <MotionNumber
              value={connectedCount}
              className='text-foreground font-medium'
            />{' '}
            {connectedNounOf(connectedCount)}
          </p>
        </header>
        <div className='flex flex-col gap-3 lg:flex-row lg:items-center'>
          <div className='-mx-4 overflow-x-auto px-4 lg:mx-0 lg:px-0'>
            <Tabs value={view} onValueChange={pickView}>
              <TabsList variant='segmented' aria-label='Show integrations'>
                {VIEWS.map((option) => (
                  <TabsTab key={option.id} value={option.id}>
                    {option.label}
                    {option.id === 'connected' && (
                      <span className='bg-foreground/[0.06] text-muted-foreground inline-flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[11px]'>
                        <MotionNumber value={connectedCount} />
                      </span>
                    )}
                  </TabsTab>
                ))}
              </TabsList>
            </Tabs>
          </div>
          <div className='relative min-w-0 lg:ms-auto lg:w-64'>
            <SearchIcon className='text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2' />
            <Input
              type='search'
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={handleSearchKeyDown}
              placeholder='Search integrations'
              aria-label='Search integrations'
              className='ps-8 pe-9'
            />
            {hasQuery && (
              <button
                type='button'
                onClick={() => setQuery('')}
                aria-label='Clear search'
                className='text-muted-foreground hover:bg-foreground/5 hover:text-foreground focus-visible:ring-ring/25 absolute end-1.5 top-1/2 inline-flex size-6 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md outline-none focus-visible:ring-[3px]'
              >
                <XIcon className='size-3.5' />
              </button>
            )}
          </div>
        </div>
        <AnimatedSize>
          <ul className='grid gap-3 sm:grid-cols-2 lg:grid-cols-3'>
            <AnimatePresence mode='popLayout' initial={false}>
              {visible.map((integration) => (
                <motion.li
                  key={integration.id}
                  layout={allowsLayout && 'position'}
                  initial={{ opacity: 0, scale: 0.98 }}
                  animate={{
                    opacity: 1,
                    scale: 1,
                    transition: CARD_TRANSITION,
                  }}
                  exit={{ opacity: 0, scale: 0.98, transition: CARD_EXIT }}
                  transition={{ layout: CARD_LAYOUT }}
                >
                  <IntegrationCard
                    integration={integration}
                    state={states[integration.id]}
                    onConnect={() => connect(integration)}
                    onDisconnect={() => disconnect(integration)}
                  />
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
          <AnimatePresence initial={false}>
            {isEmpty && (
              <motion.div
                key='empty'
                initial={{ opacity: 0 }}
                animate={{ opacity: 1, transition: CARD_TRANSITION }}
                exit={{ opacity: 0, transition: CARD_EXIT }}
              >
                <EmptyView
                  view={view}
                  query={query}
                  onClearSearch={() => setQuery('')}
                  onBrowseAll={() => setView('all')}
                />
              </motion.div>
            )}
          </AnimatePresence>
        </AnimatedSize>
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type MotionProps,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useId } from 'react';

import {
  CheckIcon,
  LoaderCircleIcon,
  RefreshCwIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

import { APPROVER, CATEGORIES, type Integration } from './data';

export type ConnectState = 'idle' | 'connecting' | 'connected' | 'failed';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

const CONNECTED_LOOK =
  'bg-success/10 text-success-foreground ring-success/25 shadow-none dark:bg-success/15 data-disabled:opacity-100 disabled:opacity-100';

const BUSY_LOOK = 'data-disabled:opacity-100 disabled:opacity-100';

export const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

function labelOf(state: ConnectState) {
  if (state === 'connecting') {
    return 'Connecting';
  }
  if (state === 'connected') {
    return 'Connected';
  }
  if (state === 'failed') {
    return 'Try again';
  }
  return 'Connect';
}

function glyphOf(state: ConnectState) {
  if (state === 'connecting') {
    return {
      key: 'connecting',
      icon: <LoaderCircleIcon className='animate-spin' />,
    };
  }
  if (state === 'connected') {
    return { key: 'connected', icon: <CheckIcon /> };
  }
  if (state === 'failed') {
    return { key: 'failed', icon: <RefreshCwIcon /> };
  }
  return null;
}

function lookOf(state: ConnectState) {
  if (state === 'connected') {
    return CONNECTED_LOOK;
  }
  if (state === 'connecting') {
    return BUSY_LOOK;
  }
  return undefined;
}

function describedByOf(isFailed: boolean, errorId: string) {
  if (isFailed) {
    return errorId;
  }
  return undefined;
}

type ConnectButtonProps = {
  name: string;
  state: ConnectState;
  errorId: string;
  onConnect: () => void;
};

/** One pill for every state: Connect becomes Connecting, then Connected or Try again, and resizes to its label. */
function ConnectButton({
  name,
  state,
  errorId,
  onConnect,
}: ConnectButtonProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const label = labelOf(state);
  const glyph = glyphOf(state);
  const isConnecting = state === 'connecting';
  const isConnected = state === 'connected';
  const isLocked = isConnecting || isConnected;
  const isFailed = state === 'failed';

  return (
    <Button
      size='sm'
      disabled={isLocked}
      focusableWhenDisabled
      aria-label={`${label}: ${name}`}
      aria-describedby={describedByOf(isFailed, errorId)}
      onClick={onConnect}
      className={lookOf(state)}
    >
      <AnimatedSize
        as='span'
        axis='width'
        contentClassName='relative flex items-center gap-1.5'
      >
        <AnimatePresence mode='popLayout' initial={false}>
          {glyph && (
            <motion.span
              key={glyph.key}
              variants={variants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              {glyph.icon}
            </motion.span>
          )}
        </AnimatePresence>
        <AnimatePresence mode='popLayout' initial={false}>
          <motion.span
            key={label}
            variants={variants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
          >
            {label}
          </motion.span>
        </AnimatePresence>
      </AnimatedSize>
    </Button>
  );
}

type IntegrationCardProps = {
  integration: Integration;
  state: ConnectState;
  onConnect: () => void;
  onDisconnect: () => void;
};

export function IntegrationCard({
  integration,
  state,
  onConnect,
  onDisconnect,
}: IntegrationCardProps) {
  const titleId = useId();
  const errorId = useId();
  const shouldReduceMotion = useReducedMotion();
  const swapVariants = swapVariantsOf(shouldReduceMotion);
  const heightPresence = heightPresenceOf(shouldReduceMotion);
  const category = CATEGORIES[integration.category];
  const plateStyle = { '--gem': category.hue } as React.CSSProperties;
  const isConnected = state === 'connected';
  const isFailed = state === 'failed';
  const IntegrationIcon = integration.icon;

  return (
    <article
      aria-labelledby={titleId}
      className={cn(CARD_SURFACE, 'flex h-full flex-col p-4')}
    >
      <div className='flex items-center gap-3'>
        <span
          aria-hidden='true'
          style={plateStyle}
          className='gem-plate flex size-9 shrink-0 items-center justify-center rounded-lg [&_svg]:size-4.5'
        >
          <IntegrationIcon />
        </span>
        <div className='min-w-0 flex-1'>
          <h3 id={titleId} className='truncate text-sm font-medium'>
            {integration.name}
          </h3>
          <p className='text-muted-foreground text-xs'>{category.label}</p>
        </div>
      </div>
      <p className='text-muted-foreground mt-3 text-[13px] leading-relaxed text-pretty'>
        {integration.description}
      </p>
      <AnimatePresence initial={false}>
        {isFailed && (
          <motion.p
            key='approval'
            id={errorId}
            {...heightPresence}
            className='text-destructive-ink overflow-hidden text-xs leading-relaxed'
          >
            <span className='block pt-2'>
              {integration.name} needs a workspace owner to approve it. A
              request went to {APPROVER}. Try again once they approve.
            </span>
          </motion.p>
        )}
      </AnimatePresence>
      <div className='mt-auto flex items-center gap-1.5 pt-4'>
        <ConnectButton
          name={integration.name}
          state={state}
          errorId={errorId}
          onConnect={onConnect}
        />
        <AnimatePresence initial={false}>
          {isConnected && (
            <motion.span
              key='disconnect'
              variants={swapVariants}
              initial='enter'
              animate='visible'
              exit='exit'
              transition={SWAP_TRANSITION}
              className='flex'
            >
              <Button
                variant='ghost'
                size='sm'
                aria-label={`Disconnect ${integration.name}`}
                onClick={onDisconnect}
              >
                Disconnect
              </Button>
            </motion.span>
          )}
        </AnimatePresence>
      </div>
    </article>
  );
}

import {
  CreditCardIcon,
  FileTextIcon,
  FolderIcon,
  GitMergeIcon,
  type Icon,
  MailIcon,
  MessageCircleIcon,
  ServerIcon,
  WalletIcon,
  ZapIcon,
} from '@/registry/ndeko/lib/icons';

export type CategoryId = 'messaging' | 'files' | 'finance' | 'developer';

export type ViewId = 'all' | 'connected' | CategoryId;

export type Integration = {
  id: string;
  name: string;
  category: CategoryId;
  icon: Icon;
  description: string;
  /** The first attempt asks for an owner's approval, so the block can show its error state. */
  needsApproval?: boolean;
};

export const PAGE = {
  title: 'Integrations',
  description:
    'Connect the tools Fernhollow Studio already uses. Each one only reads what its card says.',
};

export const CATEGORIES: Record<CategoryId, { label: string; hue: string }> = {
